<template>
  <div class="logs-view">
    <CompanyNavBar />

    <div class="card">
      <div class="card-body text-secondary">
        <b-row>
          <b-col>
            <b-row>
              <b-col lg="3"
                ><h5 class="text-dark">
                  <b-icon icon="clock-history"></b-icon> Histórico de operações
                </h5></b-col
              >
              <b-col>
                <b-row class="mb-1">
                  <!-- <b-col
                    ><b-form-select
                      v-model="selectedPaymentMethod"
                      :options="options"
                    ></b-form-select
                  ></b-col> -->
                  <b-col>
                    <b-form-datepicker
                      placeholder="M"
                      block
                      size="sm"
                      id="from-datepicker"
                      v-model="fromDate"
                    ></b-form-datepicker
                  ></b-col>
                  <b-col
                    ><b-form-datepicker
                      placeholder="Até"
                      block
                      size="sm"
                      id="to-datepicker"
                      v-model="toDate"
                    ></b-form-datepicker
                  ></b-col>
                  <b-col cols="2"
                    ><b-button
                      @click="getSystemLogs()"
                      :disabled="(!toDate && !fromDate) || isLoading"
                      size="sm"
                      variant="secondary"
                      block
                      ><b-icon icon="search"></b-icon> </b-button
                  ></b-col>
                </b-row>
              </b-col>
              <b-col lg="1">
                <b-button
                  size="sm"
                  block
                  variant="secondary"
                  @click="downloadSystemLogsPDF()"
                >
                  <b-icon icon="file-earmark-pdf-fill"></b-icon> PDF</b-button
                >
              </b-col>
              <b-col lg="1">
                <b-button
                  size="sm"
                  block
                  variant="secondary"
                  @click="downloadSystemLogsExcel()"
                >
                  <b-icon icon="file-earmark-excel-fill"></b-icon>
                  Excel</b-button
                >
              </b-col>
            </b-row>
            <b-row>
              <b-col>
                <b-overlay :show="isLoading" rounded="sm">
                  <p class="text-danger mt-1" v-if="logs.length == 0">
                    Sem nenhum histórico registado até o momento.
                  </p>
                  <table
                    v-else
                    class="table table-sm table-hover table-stripped mt-1"
                  >
                    <thead>
                      <tr
                        style="font-size: 10pt"
                        class="bg-secondary text-white"
                      >
                        <th>Acção</th>
                        <th>Descrição</th>
                        <th>Técnico</th>
                        <th>Data</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr
                        v-for="log in logs"
                        :key="log.id"
                        style="font-size: 9pt; cursor: pointer"
                      >
                        <td>{{ log.action }}</td>
                        <td>{{ log.description }}</td>
                        <td>{{ log.userName }}</td>
                        <td v-date-format="log.createdAt"></td>
                      </tr>
                    </tbody>
                  </table>
                </b-overlay>
              </b-col>
            </b-row>
          </b-col>
        </b-row>
      </div>
    </div>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";

import moment from "moment";
moment.locale("pt-br");
import exportFromJSON from "export-from-json";
import DateFormat from "@/utils/dateFormat";

import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
pdfMake.vfs = pdfFonts.pdfMake.vfs;

import CompanyNavBar from "@/components/CompanyNavBar";
export default {
  data: () => ({
    fromDate: moment().format("YYYY-MM-01"),
    toDate: moment().format("YYYY-MM-") + moment().daysInMonth(),
  }),

  components: {
    CompanyNavBar,
  },

  created() {
    this.checkPasswordStatus();
    this.getSystemLogs();
  },

  computed: {
    ...mapGetters(["isLoading", "user", "token", "company", "users", "logs"]),
  },

  methods: {
    checkPasswordStatus() {
      this.user.updatedPassword == 1 ? "" : this.$router.replace("/profile");
    },

    getSystemLogs() {
      this.$store.commit("LOADING_STATUS", true);
      const queryString = `?from=${this.fromDate}&to=${this.toDate}&companyId=${this.company.id}`;
      axios
        .get(`/api/logs/${queryString}`)
        .then((res) => {
          const { success, result, message } = res.data;
          if (success === true) {
            this.$store.commit("LOADING_STATUS", false);
            this.$store.commit("SET_LOGS", result);
          } else {
            this.showToast("Sucesso", "success", message);
            this.$store.commit("LOADING_STATUS", false);
            this.$store.commit("SET_LOGS", []);
          }
        })
        .catch((err) => {
          this.$store.commit("SET_LOGS", []);
          this.$store.commit("LOADING_STATUS", false);
          this.showToast("Erro", "danger", err.message);
          console.log(err);
        });
    },

    async downloadSystemLogsPDF() {
      const body = [];

      for (let row of this.logs) {
        const rows = [];

        // rows.push({ text: row.id, fontSize: 8 })
        rows.push({ text: DateFormat.formatDate(row.createdAt), fontSize: 8 });
        rows.push({ text: row.userName, fontSize: 8 });
        rows.push({ text: row.action, fontSize: 8 });
        rows.push({ text: row.description, fontSize: 8 });

        body.push(rows);
      }

      let docDefinition = {
        // watermark: { text: this.company[0].name, opacity: 0.08 },
        header: [
          // {
          //   image: await getBase64ImageFromURL(this.company.companyLogo),
          //   width: 300,
          //   height: 200,
          //   margin: [30, 0, 0, 0],
          // },
        ],
        footer: {
          columns: [
            {
              text: "Documento processado por computador",
              alignment: "left",
              fontSize: 8,
              margin: [30, 0, 0, 0],
            },
            {
              text: "Microcrédito Software",
              alignment: "right",
              fontSize: 8,
              margin: [0, 0, 30, 0],
            },
          ],
        },

        content: [
          {
            columns: [
              [
                {
                  text: `\nData de impressão: ${DateFormat.formatDate(
                    new Date()
                  )}`,
                  fontSize: 8,
                  alignment: "left",
                },
              ],
            ],
          },
          {
            text: "\n",
          },
          {
            text: `Histórico de operações registadas pelo sistema`,
            bold: true,
            fontSize: 12,
            alignment: "left",
          },
          {
            text: "\n",
          },
          {
            table: {
              widths: ["auto", "auto", "auto", "*"],
              body: [
                [
                  { text: "Data", style: "columnsTitle" },
                  { text: "Técnico", style: "columnsTitle" },
                  { text: "Acção", style: "columnsTitle" },
                  { text: "Descrição", style: "columnsTitle" },
                ],
                ...body,
                [{ text: "\n\n" }, {}, {}, {}],
              ],
            },
            layout: "lightHorizontalLines",
          },
        ],
        styles: {
          paymentMethodStyle: {
            bold: true,
            fontSize: 10,
          },
          sectionHeader: {
            bold: true,
            fontSize: 10,
            margin: [0, 15, 0, 15],
          },
          columnsTitle: {
            fontSize: 7,
            bold: true,
            color: "#000000",
          },
          columnsSubTotals: {
            fontSize: 8,
            bold: true,
            color: "#000000",
          },
          columnsTotal: {
            fontSize: 12,
            bold: true,
            color: "#000000",
          },
          companyDetailsStyle: {
            fontSize: 9,
            bold: true,
            color: "#000000",
          },
          customerStyle: {
            fontSize: 10,
            bold: false,
          },
        },
      };

      // pdfMake.createPdf(docDefinition).download(`proforma${this.currentQuotation.name}.pdf`);
      pdfMake.createPdf(docDefinition).open();
    },

    async downloadSystemLogsExcel() {
      const body = [];

      for (let log of this.logs) {
        const row = {
          Data: DateFormat.formatDate(log.createdAt),
          Técnico: log.userName,
          Acção: log.action,
          Descrição: log.description,
        };
        body.push(row);
      }
      const fileName = "Histórico_de_operações";
      const data = body;
      const exportType = "xls";

      exportFromJSON({ data, fileName, exportType });
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },
  },
};
</script>
